"""Build source-backed catalog data without fabricating stock or child sizing."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
sources=json.loads((ROOT/'catalog/sources.json').read_text())
jobs=json.loads((ROOT/'catalog/studio-jobs.json').read_text())+json.loads((ROOT/'catalog/additional-studio-jobs.json').read_text())
alternates={j['alternateFor']:j for j in jobs if 'alternateFor' in j}
fronts={j['frontFor']:j for j in jobs if 'frontFor' in j}
swatches={'Ivory':'#e9e0cc','Navy':'#20283f','Grey':'#a1a29d','Pink':'#e2b5bd','Black':'#22231f','Red':'#bb2829','Yellow':'#e4cc62','Blue':'#7f9bc8','Green':'#28573e','White':'#eeece1','Olive':'#55583c','Purple':'#6c3a8b','Orange':'#d96b19','Silver':'#c9cdc6','Brown':'#7e5239','Charcoal':'#4b4e4b','Sky Blue':'#9cc8df','Teal':'#218eae','Royal Blue':'#2b5eab','Mint':'#a4d9d2'}
products=[]
for j in jobs:
 if 'alternateFor' in j or 'frontFor' in j:continue
 primary=fronts.get(j['id'],j)
 image='assets/catalog/studio/'+primary['id']+'.webp'
 if not (ROOT/'dist'/image).exists():raise RuntimeError('Missing studio asset: '+image)
 source=primary['localSource'].removeprefix('dist/')
 category='Accessories' if j['family'] in ('Headwear','Socks') else 'Apparel'
 alt=alternates.get(j['id'])
 alt_image=('assets/catalog/studio/'+alt['id']+'.webp') if alt else (('assets/catalog/studio/'+j['id']+'.webp') if j['id'] in fronts else None)
 product=dict(id=j['id'],name=j['name'],color=j['color'],swatch=swatches.get(j['color'],swatches.get(j['color'].split(' ')[0],'#b6a785')),family=j['family'],category=category,department='unisex',departments=['men','women'],ref='WG-'+str(len(products)+1).zfill(3),image=image,sourceImage=source,sourceName=Path(primary['source']).name,sourceNumber=primary['number'],photoStatus='Studio edit',referenceOnly=j['status']=='Design reference',detail='Selected from the supplied '+j['color'].lower()+' '+j['family'].lower()+' photography. This individual studio view was prepared from the supplied image; compare the original photo for exact artwork and construction. Sizes, materials, stock and pricing require confirmation.')
 if alt_image:product['backImage']=alt_image
 if primary is not j:
  product['extraSourceImage']=j['localSource'].removeprefix('dist/');product['supportingSourceNumber']=j['number']
 if product['referenceOnly']:product['detail']='Wholesale Gods black-and-gold hoodie design supplied as an application reference. This is a design concept, not confirmed manufactured stock.'
 products.append(product)
assert len({p['id'] for p in products})==len(products)
(ROOT/'catalog/products.json').write_text(json.dumps(products,indent=2))
(ROOT/'dist/catalog.js').write_text('/* Source-backed garment collection. Generated by scripts/build_catalog.py. */\nwindow.WGCatalog = '+json.dumps(products,ensure_ascii=False,separators=(',',':'))+';\n')
used={j['number'] for j in jobs}
duplicates={10:'Alternate model view of baseball knit, represented by source 42.',16:'Color overview; individual S beanies use sources 17–22.',23:'Color overview; individual horned S beanies use sources 24–28.',29:'Color overview; individual box-logo beanies use sources 30–34.',36:'Duplicate black-sock view, represented by source 35.',37:'Duplicate black-sock view, represented by source 35.',38:'Black-sock packaging reference, retained beside source 35.',40:'White-sock packaging reference, retained beside source 39.'}
for s in sources:
 s['productIds']=[p['id'] for p in products if (p['sourceNumber']==s['number'] or p.get('supportingSourceNumber')==s['number'])]
 s['status']='Individual pieces prepared' if s['number'] in used else ('Duplicate / supporting view' if s['number'] in duplicates else 'Reference board')
 s['note']=duplicates.get(s['number'],'Dense assortment/pricing board retained as a reference; its small thumbnails are not treated as verified individual stock.') if s['number'] not in used else 'Individual studio edits are linked to their supplied original.'
(ROOT/'catalog/sources.json').write_text(json.dumps(sources,indent=2))
public=[dict(number=s['number'],name=Path(s['file']).name,image=s['local'].removeprefix('dist/'),status=s['status'],note=s['note'],products=s['productIds']) for s in sources]
(ROOT/'dist/source-data.js').write_text('window.WGSourceLibrary = '+json.dumps(public,ensure_ascii=False,separators=(',',':'))+';\n')
print(f'Built {len(products)} individual source-backed records from {len(sources)} supplied files. Kids awaits confirmed items.')
